async function request(method, url, body) {
    const res = await fetch(url, {
        method,
        headers: {
            'Accept': 'application/json',
            ...(body ? { 'Content-Type': 'application/json' } : {}),
        },
        body: body ? JSON.stringify(body) : undefined,
    });

    const data = await res.json().catch(() => ({}));

    if (!res.ok) {
        const err = new Error(data.message || `请求失败（${res.status}）`);
        err.validation = data.errors || null;
        throw err;
    }
    return data;
}

export const api = {
    get: (url) => request('GET', url),
    post: (url, body) => request('POST', url, body),
};

export const CHANNEL_LABELS = { website: '官网', screen: '店内屏', delivery: '外卖平台' };
export const CHANNELS = ['website', 'screen', 'delivery'];

export const ADJ_STATUS = {
    pending: { label: '审核中', cls: 'st-pending' },
    approved: { label: '已批准·生效中', cls: 'st-approved' },
    rejected: { label: '已驳回', cls: 'st-rejected' },
    superseded: { label: '已被新版本取代', cls: 'st-superseded' },
    expired: { label: '已到期恢复', cls: 'st-expired' },
};

export const RECEIPT_STATUS = {
    success: { label: '已同步', cls: 'rc-success' },
    failed: { label: '失败', cls: 'rc-failed' },
    pending: { label: '等待回执', cls: 'rc-pending' },
    stale_ignored: { label: '晚到已忽略', cls: 'rc-stale' },
};

export const TASK_STATUS = {
    pending: { label: '待执行', cls: 'st-pending' },
    done: { label: '已执行恢复', cls: 'st-approved' },
    cancelled_superseded: { label: '因延期被取消', cls: 'st-superseded' },
    skipped_stale: { label: '已失效·跳过', cls: 'st-expired' },
};

export function fmt(dt) {
    return dt ? dt.slice(0, 16) : '—';
}

export function fmtDate(dt) {
    return dt ? dt.slice(0, 10) : '—';
}

import React, { useCallback, useEffect, useState } from 'react';
import { api } from './api';
import CalendarPage from './components/CalendarPage';
import AdjustmentsPage from './components/AdjustmentsPage';
import ChannelsPage from './components/ChannelsPage';

const TABS = [
    { key: 'calendar', label: '门店日历' },
    { key: 'adjustments', label: '调整申请' },
    { key: 'channels', label: '渠道状态' },
];

export default function App() {
    const [stores, setStores] = useState([]);
    const [storeId, setStoreId] = useState(null);
    const [tab, setTab] = useState('calendar');
    const [toast, setToast] = useState(null);

    useEffect(() => {
        api.get('/api/stores').then((list) => {
            setStores(list);
            if (list.length && !storeId) setStoreId(list[0].id);
        }).catch((e) => showToast(e.message, 'error'));
    }, []);

    const showToast = useCallback((message, kind = 'ok') => {
        setToast({ message, kind });
        setTimeout(() => setToast(null), 4000);
    }, []);

    const store = stores.find((s) => s.id === storeId);

    return (
        <div className="page">
            <header className="topbar">
                <div className="brand">
                    <span className="brand-mark">⏱</span>
                    <div>
                        <h1>营业时间调整与渠道同步</h1>
                        <p>一次申请 · 总部审批 · 官网 / 店内屏 / 外卖平台同步发布</p>
                    </div>
                </div>
                <label className="store-picker">
                    门店
                    <select value={storeId ?? ''} onChange={(e) => setStoreId(Number(e.target.value))}>
                        {stores.map((s) => (
                            <option key={s.id} value={s.id}>{s.name}（{s.code}）</option>
                        ))}
                    </select>
                </label>
            </header>

            <nav className="tabs">
                {TABS.map((t) => (
                    <button
                        key={t.key}
                        className={tab === t.key ? 'tab active' : 'tab'}
                        onClick={() => setTab(t.key)}
                    >
                        {t.label}
                    </button>
                ))}
            </nav>

            <main>
                {store && tab === 'calendar' && <CalendarPage store={store} />}
                {store && tab === 'adjustments' && <AdjustmentsPage store={store} showToast={showToast} />}
                {store && tab === 'channels' && <ChannelsPage store={store} showToast={showToast} />}
            </main>

            {toast && <div className={`toast toast-${toast.kind}`}>{toast.message}</div>}
        </div>
    );
}

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

createRoot(document.getElementById('app')).render(<App />);

