:root {
    --bg: #f4f6fa;
    --card: #ffffff;
    --ink: #1f2733;
    --muted: #6b7686;
    --line: #e3e8f0;
    --primary: #2563eb;
    --primary-dark: #1d4ed8;
    --ok: #15803d;
    --ok-bg: #e7f6ec;
    --warn: #b45309;
    --warn-bg: #fdf3e3;
    --bad: #b91c1c;
    --bad-bg: #fdeaea;
    --gray-bg: #eef1f6;
}

* { box-sizing: border-box; }

body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
    font-size: 14px;
}

.page { max-width: 1180px; margin: 0 auto; padding: 20px 16px 60px; }

/* 顶栏 */
.topbar {
    display: flex; justify-content: space-between; align-items: center;
    gap: 16px; flex-wrap: wrap; margin-bottom: 14px;
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark {
    width: 44px; height: 44px; border-radius: 12px; background: var(--primary);
    color: #fff; display: flex; align-items: center; justify-content: center; font-size: 22px;
}
.brand h1 { font-size: 19px; margin: 0; }
.brand p { margin: 2px 0 0; color: var(--muted); font-size: 12px; }
.store-picker { display: flex; align-items: center; gap: 8px; color: var(--muted); }
.store-picker select { min-width: 240px; }

/* 标签页 */
.tabs { display: flex; gap: 6px; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.tab {
    border: none; background: none; padding: 10px 18px; cursor: pointer;
    font-size: 15px; color: var(--muted); border-bottom: 2px solid transparent;
}
.tab.active { color: var(--primary); border-bottom-color: var(--primary); font-weight: 600; }

/* 卡片 */
.card {
    background: var(--card); border: 1px solid var(--line); border-radius: 12px;
    padding: 16px 18px; margin-bottom: 16px;
}
.card h3 { margin: 0 0 10px; font-size: 16px; }
.card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.card-head h3 { margin: 0; display: flex; align-items: center; gap: 8px; }
.hint { color: var(--muted); font-size: 12px; margin: 4px 0 12px; }
.muted { color: var(--muted); }
.small { font-size: 12px; }

/* 表单 */
input, select {
    padding: 7px 10px; border: 1px solid var(--line); border-radius: 8px;
    font-size: 14px; background: #fff; color: var(--ink);
}
input:focus, select:focus { outline: 2px solid rgba(37, 99, 235, .25); border-color: var(--primary); }
label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--muted); }
label.grow { flex: 1; }
.form-row { display: flex; gap: 12px; flex-wrap: wrap; align-items: flex-end; margin-bottom: 10px; }
.form-actions { display: flex; gap: 10px; margin-top: 6px; }
.field-error { color: var(--bad); font-size: 12px; margin: 2px 0; }

.btn {
    border: 1px solid var(--line); background: #fff; color: var(--ink);
    padding: 7px 14px; border-radius: 8px; cursor: pointer; font-size: 13px;
}
.btn:hover { border-color: var(--primary); color: var(--primary); }
.btn.primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-dark); }
.btn.ok { background: var(--ok); border-color: var(--ok); color: #fff; }
.btn.danger { background: #fff; border-color: var(--bad); color: var(--bad); }
.btn.danger:hover { background: var(--bad-bg); }
.btn.ghost { border-color: transparent; color: var(--primary); }
.btn.tiny { padding: 2px 8px; font-size: 12px; border-radius: 6px; }
.btn:disabled { opacity: .6; cursor: default; }

.tag {
    display: inline-block; padding: 1px 8px; border-radius: 999px;
    background: var(--gray-bg); color: var(--muted); font-size: 12px;
}
.tag.ok { background: var(--ok-bg); color: var(--ok); }
.tag.warn { background: var(--warn-bg); color: var(--warn); }

/* 状态徽章 */
.status { display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: 12px; }
.st-pending { background: var(--warn-bg); color: var(--warn); }
.st-approved { background: var(--ok-bg); color: var(--ok); }
.st-rejected { background: var(--bad-bg); color: var(--bad); }
.st-superseded { background: var(--gray-bg); color: var(--muted); }
.st-expired { background: var(--gray-bg); color: var(--muted); }

/* 日历 */
.calendar-layout { display: grid; grid-template-columns: 1fr 300px; gap: 16px; align-items: start; }
.cal-head { display: flex; justify-content: space-between; align-items: center; }
.cal-head h2 { margin: 0; font-size: 17px; }
.cal-grid {
    display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; margin-top: 8px;
}
.cal-weekday { text-align: center; color: var(--muted); font-size: 12px; padding: 4px 0; }
.cal-cell {
    min-height: 74px; border: 1px solid var(--line); border-radius: 8px;
    padding: 5px 7px; position: relative; background: #fff;
}
.cal-cell.outside { opacity: .38; }
.cal-cell.today { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary) inset; }
.cal-cell.adjusted { background: #fff8ec; border-color: #f2d8a7; }
.cal-cell.closed { background: #f6f7f9; }
.cal-cell.adjusted.closed { background: #fdeeee; border-color: #f0bcbc; }
.cal-date { font-weight: 600; font-size: 13px; }
.cal-hours { font-size: 12px; color: var(--ink); margin-top: 3px; }
.cal-hours.off { color: var(--muted); }
.cal-badge {
    position: absolute; right: 4px; top: 4px; font-size: 10px; padding: 0 6px;
    border-radius: 999px; background: var(--warn-bg); color: var(--warn);
}
.cal-badge.closure { background: var(--bad-bg); color: var(--bad); }
.legend { display: flex; gap: 16px; margin-top: 12px; color: var(--muted); font-size: 12px; }
.legend .dot { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 4px; }
.dot.base { background: #fff; border: 1px solid var(--line); }
.dot.adj { background: #fff8ec; border: 1px solid #f2d8a7; }
.dot.closed { background: #f6f7f9; border: 1px solid var(--line); }

.side .draft-item { border-top: 1px dashed var(--line); padding: 8px 0; }
.draft-title { font-weight: 600; margin-bottom: 2px; }

/* 调整链 */
.chain .version-row {
    border-top: 1px solid var(--line); padding: 12px 0;
    display: flex; justify-content: space-between; gap: 14px; flex-wrap: wrap;
}
.chain .version-row:first-of-type { border-top: none; }
.version-row.superseded, .version-row.expired, .version-row.rejected { opacity: .72; }
.version-main { flex: 1; min-width: 320px; }
.version-title { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 3px; }
.version-actions { display: flex; gap: 8px; align-items: flex-start; }
.sync-line { margin-top: 4px; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.sync-dots { display: inline-flex; gap: 6px; }
.sync-dot { font-size: 12px; padding: 1px 8px; border-radius: 999px; }
.sync-dot.ok { background: var(--ok-bg); color: var(--ok); }
.sync-dot.bad { background: var(--bad-bg); color: var(--bad); }
.sync-dot.wait { background: var(--warn-bg); color: var(--warn); }

.adj-form {
    border: 1px dashed var(--line); border-radius: 10px; padding: 12px 14px;
    margin-top: 10px; width: 100%; background: #fbfcfe;
}
.adj-form h4 { margin: 0 0 10px; font-size: 14px; }

/* 渠道卡片 */
.channel-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.channel-card {
    border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; background: #fbfcfe;
}
.channel-name { font-weight: 700; margin-bottom: 4px; }
.channel-summary { margin-bottom: 4px; }

/* 发布记录 */
.pub { border-top: 1px solid var(--line); padding: 10px 0; }
.pub:first-of-type { border-top: none; }
.pub-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.receipts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.receipt { border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }
.receipt-head { display: flex; align-items: center; gap: 8px; margin-bottom: 2px; }
.receipt-status { font-size: 12px; }
.rc-success { border-color: #bfe3cb; background: #f4fbf6; }
.rc-success .receipt-status { color: var(--ok); }
.rc-failed { border-color: #f0bcbc; background: #fdf5f5; }
.rc-failed .receipt-status { color: var(--bad); }
.rc-pending { border-color: #f2d8a7; background: #fffaef; }
.rc-pending .receipt-status { color: var(--warn); }
.rc-stale { background: var(--gray-bg); }
.rc-stale .receipt-status { color: var(--muted); }

/* 表格 */
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line); font-size: 13px; }
.table th { color: var(--muted); font-weight: 500; font-size: 12px; }

/* 模拟面板 */
.sim { background: #fbfcff; }

/* 提示条 */
.toast {
    position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
    padding: 10px 20px; border-radius: 10px; color: #fff; font-size: 14px;
    box-shadow: 0 6px 24px rgba(0, 0, 0, .18); z-index: 50;
}
.toast-ok { background: #166534; }
.toast-error { background: #b91c1c; }

@media (max-width: 900px) {
    .calendar-layout { grid-template-columns: 1fr; }
    .channel-cards, .receipts { grid-template-columns: 1fr; }
}

