.rc-stale { background: var(--gray-bg); }
.rc-stale .receipt-status { color: var(--muted); }

/* 表格 */
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line); font-size: 13px; }
.table th { color: var(--muted); font-weight: 500; font-size: 12px; }

/* 模拟面板 */
.sim { background: #fbfcff; }

/* 提示条 */
.toast {
    position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
    padding: 10px 20px; border-radius: 10px; color: #fff; font-size: 14px;
    box-shadow: 0 6px 24px rgba(0, 0, 0, .18); z-index: 50;
}
.toast-ok { background: #166534; }
.toast-error { background: #b91c1c; }

@media (max-width: 900px) {
    .calendar-layout { grid-template-columns: 1fr; }
    .channel-cards, .receipts { grid-template-columns: 1fr; }
}

